def main():
    out_dir = Path("./Overleaf_MTAP_Project")
    out_dir.mkdir(parents=True, exist_ok=True)

    tex_path = out_dir / "main_mtap_manuscript.tex"
    bib_path = out_dir / "references.bib"
    tex_path.write_text(TEX_CONTENT, encoding="utf-8")
    bib_path.write_text(BIB_CONTENT, encoding="utf-8")

    plt.rcParams.update({"font.size": 10, "figure.dpi": 300})
    levels_labels = ["Level 1\n(Clean)", "Level 2\n(Mild Occl.)", "Level 3\n(Burst Drop.)", "Level 4\n(Long-Tail)"]
    x = np.arange(len(levels_labels))
    width = 0.20

    shrec_mpjpe = {
        "Kinematic-Filter": [31.776, 33.617, 42.783, 29.884],
        "BiLSTM-Baseline":  [2.976,  13.208, 18.441, 38.704],
        "TCN-1D-Baseline":  [3.160,  13.355, 12.435, 35.269],
        "Proposed KAR-STGCN": [1.850, 5.218,  9.174, 12.115]
    }
    fpha_mpjpe = {
        "Kinematic-Filter": [13.263, 24.901, 63.880, 91.505],
        "BiLSTM-Baseline":  [4.832,  31.187, 19.789, 72.402],
        "TCN-1D-Baseline":  [5.409,  31.436, 21.393, 72.897],
        "Proposed KAR-STGCN": [4.475, 12.175, 18.464, 20.822]
    }

    fig, axes = plt.subplots(1, 2, figsize=(11, 4.2))
    colors = ["#7f8c8d", "#2980b9", "#e67e22", "#c0392b"]
    for idx, (m_name, vals) in enumerate(shrec_mpjpe.items()):
        axes[0].bar(x + (idx - 1.5) * width, vals, width, label=m_name, color=colors[idx], edgecolor="black", linewidth=0.5)
    axes[0].set_title("(a) SHREC'17 Benchmark: MPJPE Across Degradation Levels")
    axes[0].set_xticks(x)
    axes[0].set_xticklabels(levels_labels)
    axes[0].set_ylabel("MPJPE (mm) $\\downarrow$")
    axes[0].grid(axis="y", linestyle="--", alpha=0.4)
    axes[0].legend(loc="upper left", frameon=True)

    for idx, (m_name, vals) in enumerate(fpha_mpjpe.items()):
        axes[1].bar(x + (idx - 1.5) * width, vals, width, label=m_name, color=colors[idx], edgecolor="black", linewidth=0.5)
    axes[1].set_title("(b) FPHA Benchmark: MPJPE Across Degradation Levels")
    axes[1].set_xticks(x)
    axes[1].set_xticklabels(levels_labels)
    axes[1].set_ylabel("MPJPE (mm) $\\downarrow$")
    axes[1].grid(axis="y", linestyle="--", alpha=0.4)
    axes[1].legend(loc="upper left", frameon=True)

    plt.tight_layout()
    pdf_fig = out_dir / "fig1_multilevel_mpjpe_comparison.pdf"
    png_fig = out_dir / "fig1_multilevel_mpjpe_comparison.png"
    plt.savefig(pdf_fig, bbox_inches="tight")
    plt.savefig(png_fig, bbox_inches="tight")
    plt.close()

    zip_path = Path("./Overleaf_MTAP_Manuscript_Package.zip")
    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.write(tex_path, arcname="main_mtap_manuscript.tex")
        zf.write(bib_path, arcname="references.bib")
        zf.write(pdf_fig, arcname="fig1_multilevel_mpjpe_comparison.pdf")
        zf.write(png_fig, arcname="fig1_multilevel_mpjpe_comparison.png")

    print(f"[SUCCESS] สร้างไฟล์ ZIP สำหรับ Overleaf สำเร็จที่: {zip_path.resolve()}")

if __name__ == "__main__":
    main()
